/**
 * Frozen catalog of the public ClickUp API (specs 0009).
 *
 * `catalog.json` is generated by `scripts/generate-api.ts` from the official
 * OpenAPI files in `api/` and embedded in the binary. Each entry describes
 * one operation: id, version, method, path, CLI name (`v2-get-task`), MCP
 * tool name (`clickupfy_api_v2_get_task`), group, effect, parameters and
 * request body. This module looks operations up and builds the Zod input
 * shape shared by `api call`, `api describe` and the catalog tools.
 */
import { z, type ZodType } from "zod";
import { error } from "../app/errors.ts";
import generated from "./catalog.json" with { type: "json" };

/** JSON Schema as published by the vendor. */
export type Schema = Record<string, any>;

/** One OpenAPI parameter of an operation. */
export interface ApiParameter {
  name: string;
  in: string;
  required?: boolean;
  style?: string;
  explode?: boolean;
  schema: Schema;
}

/** One operation of the catalog. */
export interface ApiOperation {
  id: string;
  version: "v2" | "v3";
  method: string;
  path: string;
  cli: string;
  tool: string;
  group: string;
  readOnly: boolean;
  deprecated: boolean;
  authenticated: boolean;
  parameters: ApiParameter[];
  request: { required?: boolean; content?: Record<string, { schema?: Schema }> };
  documentation: string;
}

/** Every operation of the catalog, in generation order. */
export const apiOperations = generated.operations as unknown as ApiOperation[];
/** Source URLs and SHA-256 of the specifications used by the generator. */
export const apiSources = generated.sources as Array<{ version: string; url: string; sha256: string }>;

/** Pattern of the catalog tool names, documented in `docs/mcp.md`. */
export const API_TOOL_PATTERN = /^clickupfy_api_v[23]_[a-z0-9_]+$/;

/**
 * Finds an operation by operationId, CLI name or tool name. Arbitrary URLs
 * or methods are never accepted. An unknown name raises NOT_FOUND (6).
 */
export function findApiOperation(name: string): ApiOperation {
  const found = apiOperations.find((o) => o.id === name || o.cli === name || o.tool === name);
  if (!found) throw error.notFound(`Unknown API operation: ${name}. Use "clickupfy api list".`, { operation: name });
  return found;
}

/** Converts OpenAPI 3.0 `nullable` and drops descriptive fields from a schema. */
export function normalizeSchema(schema: Schema): Schema {
  const result: Schema = { ...schema };
  delete result.description;
  delete result.example;
  delete result.examples;
  delete result.default;
  if (result.properties) {
    result.type ??= "object";
    result.properties = Object.fromEntries(Object.entries(result.properties).map(([k, v]) => [k, normalizeSchema(v as Schema)]));
  }
  if (result.items) result.items = normalizeSchema(result.items);
  for (const key of ["anyOf", "oneOf", "allOf"]) {
    if (Array.isArray(result[key])) result[key] = result[key].map(normalizeSchema);
  }
  if (result.additionalProperties && typeof result.additionalProperties === "object") {
    result.additionalProperties = normalizeSchema(result.additionalProperties);
  }
  if (result.nullable) {
    delete result.nullable;
    return { anyOf: [result, { type: "null" }] };
  }
  return result;
}

/** Multipart file sent as explicit data; the MCP server never opens local paths. */
export const fileSchema = z.object({
  field: z.string().min(1).describe("Multipart field, such as attachment or attachment[0]."),
  filename: z.string().min(1),
  contentBase64: z.string().regex(/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/),
  contentType: z.string().optional(),
});

/** Input envelope of a catalog operation. */
export interface ApiInput {
  path?: Record<string, unknown>;
  query?: Record<string, unknown>;
  headers?: Record<string, unknown>;
  body?: unknown;
  contentType?: string;
  files?: Array<z.infer<typeof fileSchema>>;
  confirm?: boolean;
}

const shapes = new Map<string, Record<string, ZodType>>();

/**
 * Builds the Zod shape of an operation input: `path`, `query`, `headers`,
 * `body`, `contentType`, `files` (multipart) and `confirm` (DELETE). Numeric
 * path ids also accept digit strings. `optional` lists parameters
 * (`path:list_id`) that become optional because an MCP server pins them.
 * Shapes without `optional` are cached per operation.
 */
export function operationShape(operation: ApiOperation, optional: ReadonlySet<string> = new Set()): Record<string, ZodType> {
  const cached = optional.size ? undefined : shapes.get(operation.id);
  if (cached) return cached;
  const shape: Record<string, ZodType> = {};
  for (const location of ["path", "query", "header"]) {
    const fields: Record<string, ZodType> = {};
    let required = false;
    for (const param of operation.parameters.filter((p) => p.in === location)) {
      // Content-Type is chosen by the transport from the documented formats.
      if (location === "header" && param.name.toLowerCase() === "content-type") continue;
      let field: ZodType = z.fromJSONSchema(normalizeSchema(param.schema) as never);
      if (location === "path") {
        if (["number", "integer"].includes(param.schema.type)) field = z.union([field, z.string().regex(/^\d+$/)]);
        if (param.schema.type === "string") field = field.refine((v) => typeof v === "string" && v.trim().length > 0, "Provide a non-empty value.");
      }
      const isRequired = param.required === true && !optional.has(`${location}:${param.name}`);
      fields[param.name] = isRequired ? field : field.optional();
      required ||= isRequired;
    }
    if (Object.keys(fields).length) {
      const object = z.strictObject(fields);
      shape[location === "header" ? "headers" : location] = required ? object : object.optional();
    }
  }
  const content = operation.request.content ?? {};
  const types = Object.keys(content);
  if (types.length) {
    const schemas = types.map((type) => z.fromJSONSchema(normalizeSchema(content[type]?.schema ?? {}) as never));
    const body = schemas.length === 1 ? (schemas[0] as ZodType) : z.union(schemas as [ZodType, ZodType, ...ZodType[]]);
    shape.body = operation.request.required && !types.includes("multipart/form-data") ? body : body.optional();
    shape.contentType = z.enum(types as [string, ...string[]]).optional();
  }
  if (types.includes("multipart/form-data")) shape.files = z.array(fileSchema).min(1);
  if (operation.method === "DELETE") shape.confirm = z.literal(true).describe("Must be true: confirms the deletion or removal.");
  if (!optional.size) shapes.set(operation.id, shape);
  return shape;
}

/** JSON Schema of the operation input, as returned by `api describe`. */
export function operationInputSchema(operation: ApiOperation): unknown {
  return z.toJSONSchema(z.strictObject(operationShape(operation)), { unrepresentable: "any" });
}
